import { describe, it, expect } from "vitest";
import { appliquerRemise } from "./remise.js";

describe("appliquerRemise", () => {
  it("applique 10 % au-dessus de 100 €", () => {
    // arrange
    const panier = { total: 200 };
    // act
    const resultat = appliquerRemise(panier, 10);
    // assert
    expect(resultat).toBe(180);
  });

  it("laisse le total inchangé sous le seuil", () => {
    expect(appliquerRemise({ total: 50 }, 10)).toBe(50);
  });
});

